.darma-loader-darma-b9-rolling-wheel { --accent: var(--loader-color, #334155); --accent-2: var(--loader-secondary-color, #f59e0b); width: var(--loader-size, 88px); height: calc(var(--loader-size, 88px) * .58); position: relative; }
.darma-loader-darma-b9-rolling-wheel::after { content: ''; position: absolute; left: 0; right: 0; bottom: 6%; height: 2px; background: color-mix(in srgb, var(--accent) 30%, transparent); }
.darma-loader-darma-b9-rolling-wheel span { position: absolute; left: 0; bottom: 8%; width: calc(var(--loader-size, 88px) * .5); height: calc(var(--loader-size, 88px) * .5); border-radius: 50%; border: calc(var(--loader-size, 88px) * .05) solid var(--accent); box-sizing: border-box; animation: darma-loader-darma-b9-rolling-wheel-roll calc(var(--loader-speed, 1s) * 2) linear infinite; }
.darma-loader-darma-b9-rolling-wheel span::before, .darma-loader-darma-b9-rolling-wheel span::after { content: ''; position: absolute; inset: 28% 46%; background: var(--accent-2); border-radius: 2px; }
.darma-loader-darma-b9-rolling-wheel span::after { transform: rotate(90deg); }
@keyframes darma-loader-darma-b9-rolling-wheel-roll { 0% { transform: translateX(0) rotate(0deg); } 100% { transform: translateX(calc(var(--loader-size, 88px) * .5)) rotate(360deg); } }

